size(43, 80, 48, 1.25);
name("wooden farmhouse chair");

var CX = 21.5;
var PAL = ["own", "3:8", "2:8", "3:2", "own", "2:8"];
var DARK = "2:9";
function wc() { return PAL[Math.floor(rng() * PAL.length)]; }

// a limb in short segments of slightly different tone, like grain
function limb(x0, y0, z0, x1, y1, z1, r0, r1) {
  var dx = x1 - x0, dy = y1 - y0, dz = z1 - z0;
  var len = Math.sqrt(dx * dx + dy * dy + dz * dz);
  var n = Math.max(1, Math.round(len / 4));
  for (var i = 0; i < n; i++) {
    var a = i / n, b = (i + 1) / n;
    tube("wood", wc(),
      x0 + dx * a, y0 + dy * a, z0 + dz * a,
      x0 + dx * b, y0 + dy * b, z0 + dz * b,
      r0 + (r1 - r0) * a, r0 + (r1 - r0) * b);
  }
}

function frontLeg(s, y) { var t = y / 33; return [CX + s * (17 - t), y, 4.5 + 1.5 * t]; }
function backLeg(s, y) { var t = y / 34; return [CX + s * (15.5 - 0.5 * t), y, 42 - 5 * t]; }
function post(s, y) { var t = (y - 34) / 43; return [CX + s * (15 - 0.5 * t), y, 37 + 7 * t]; }

// aprons under the seat
for (var x = 6; x < 37; x++) {
  for (var y = 29; y < 33; y++) {
    var c = (y === 29) ? DARK : (rng() < 0.3 ? "2:8" : "3:8");
    put("wood", c, x, y, 6); put("wood", c, x, y, 7);
    put("wood", c, x, y, 36); put("wood", c, x, y, 37);
  }
}
for (var z = 6; z < 38; z++) {
  for (var y2 = 29; y2 < 33; y2++) {
    var c2 = (y2 === 29) ? DARK : (rng() < 0.3 ? "2:8" : "3:8");
    put("wood", c2, 5, y2, z); put("wood", c2, 6, y2, z);
    put("wood", c2, 36, y2, z); put("wood", c2, 37, y2, z);
  }
}

// legs and back posts
[-1, 1].forEach(function (s) {
  var a = frontLeg(s, 0), b = frontLeg(s, 33);
  limb(a[0], 0, a[2], b[0], 33, b[2], 1.3, 1.9);
  // turned rings on front legs
  var r1 = frontLeg(s, 24), r2 = frontLeg(s, 6);
  ball("wood", "2:8", r1[0], 24, r1[2], 2.4, 1.2, 2.4);
  ball("wood", "2:8", r2[0], 6, r2[2], 2.0, 1.0, 2.0);
  var c = backLeg(s, 0), d = backLeg(s, 34);
  limb(c[0], 0, c[2], d[0], 34, d[2], 1.4, 1.9);
  var e = post(s, 34), f = post(s, 77);
  limb(e[0], 34, e[2], f[0], 77, f[2], 1.9, 1.4);
  ball("wood", "2:8", f[0], 77.5, f[2], 1.9, 1.9, 1.9);
  // side stretchers
  var p = frontLeg(s, 10), q = backLeg(s, 10);
  limb(p[0], 10, p[2], q[0], 10, q[2], 1.1, 1.1);
  var p2 = frontLeg(s, 20), q2 = backLeg(s, 20);
  limb(p2[0], 20, p2[2], q2[0], 20, q2[2], 1.0, 1.0);
});
// front and back stretchers
var fl = frontLeg(-1, 15), fr = frontLeg(1, 15);
limb(fl[0], 15, fl[2], fr[0], 15, fr[2], 1.1, 1.1);
ball("wood", "2:8", CX, 15, fl[2], 3, 1.6, 1.6);
var bl = backLeg(-1, 15), br = backLeg(1, 15);
limb(bl[0], 15, bl[2], br[0], 15, br[2], 1.1, 1.1);

// seat: planks running front to back, wider at the front, rounded corners
var plankCol = [];
for (var i = 0; i < 8; i++) plankCol.push(wc());
for (var z3 = 3; z3 < 40; z3++) {
  var t = (z3 - 3) / 36;
  var hw = 19.5 - 3 * t;
  if (z3 < 6) hw -= (6 - z3) * (6 - z3) * 0.35;
  if (z3 > 37) hw -= (z3 - 37) * 0.8;
  for (var x3 = 0; x3 < 43; x3++) {
    var dx = Math.abs(x3 + 0.5 - CX);
    for (var y3 = 33; y3 < 36; y3++) {
      var lim = hw - (y3 === 33 ? 1 : 0);
      if (y3 === 33 && z3 < 4) continue;
      if (dx > lim) continue;
      var pl = Math.floor((x3 + 2) / 6);
      var col = plankCol[pl % 8];
      if (rng() < 0.2) col = wc();
      if (y3 === 35 && (x3 + 2) % 6 === 0) col = DARK;
      if (y3 === 33) col = DARK;
      // gentle saddle dip in the top
      if (y3 === 35 && dx < 11 && z3 > 12 && z3 < 32 && ((dx / 11) * (dx / 11) + Math.pow((z3 - 22) / 10, 2)) < 1) {
        if (at(x3, 34, z3) !== null || true) { continue; }
      }
      put("wood", col, x3, y3, z3);
    }
  }
}

// back: bowed crest rail, lower rail and slats between
function backZ(x, y) {
  var u = (x + 0.5 - CX) / 14.5;
  return 37 + 7 * (y - 34) / 43 + 2.5 * (1 - u * u) - 0.5;
}
for (var xb = 7; xb < 36; xb++) {
  var u = (xb + 0.5 - CX) / 14.5;
  var top = 75 + Math.round(2.5 * (1 - u * u));
  var m = (((xb - 21) % 5) + 5) % 5;
  var slat = (m === 0 || m === 1 || m === 4) && xb >= 9 && xb <= 33;
  var sc = PAL[(Math.floor((xb - 21 + 1 + 50) / 5)) % PAL.length];
  for (var yb = 45; yb < top; yb++) {
    var crest = yb >= 67, lower = yb < 49;
    if (!crest && !lower && !slat) continue;
    var zc = Math.floor(backZ(xb, yb));
    var col2;
    if (crest) col2 = (yb === 67) ? DARK : (rng() < 0.25 ? "3:8" : (yb % 3 === 0 ? "2:8" : "own"));
    else if (lower) col2 = (yb === 45) ? DARK : (rng() < 0.3 ? "3:8" : "2:8");
    else col2 = rng() < 0.2 ? "3:2" : sc;
    put("wood", col2, xb, yb, zc);
    put("wood", col2, xb, yb, zc + 1);
    if (crest || lower) put("wood", col2, xb, yb, zc + 2);
  }
}
// pegs where the rails join the posts
[-1, 1].forEach(function (s) {
  [47, 71].forEach(function (y) {
    var p = post(s, y);
    put("wood", "2:6", Math.floor(p[0]), y, Math.floor(p[2] - 1.7));
  });
});
